"""Five choice edge cases with actual funded queue and recorded before/after state."""
from test_mobile_rendering import ROOT,html
from playwright.sync_api import sync_playwright
import ast,json,hashlib
source=(ROOT/'assets/game.js').read_text();tree=ast.parse((ROOT/'tests/test_logistics_recovery.py').read_text());fixture=next(ast.literal_eval(n.value)for n in tree.body if isinstance(n,ast.Assign)and any(isinstance(t,ast.Name)and t.id=='probe'for t in n.targets))
extra=r'''window.__edge={snapshot:()=>({day:G.day,treasury:G.treasury,total:totalMoney(),priority:G.regionalTrade.priority,reliefUntil:G.regionalTrade.reliefUntil,queue:G.regionalTrade.shipments.filter(o=>o.depot===-1&&['loading','unloading'].includes(o.stage)).map(o=>({id:o.id,stage:o.stage,handled:o.handled,qty:o.qty})),calendar:G.civicCalendar?.events.map(e=>({id:e.id,status:e.status}))||[]}),review:()=>{window.__choiceReview=reviewMarketLoadingChoice();return {ok:__choiceReview.ok,reason:__choiceReview.reason}},authorize:()=>authorizeMarketLoadingChoice(window.__choiceReview),poor:()=>{G.region+=G.treasury-.35;G.treasury=.35},event:()=>{const site=publicPlaceOffer();construct('square',site.x,site.y);const b=buildingAt(site.x,site.y),q=reviewCivicGathering({venue:b.id,start:G.day+5});if(!q.ok||!authorizeCivicGathering(q).ok)throw Error('Actual gathering setup failed');return G.civicCalendar.events.at(-1).id;},cancel:id=>cancelCivicGathering(id)};'''
rows=[]
with sync_playwright()as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);p=b.new_page();p.set_default_timeout(120000);errors=[];p.on('pageerror',lambda e:errors.append(str(e)));p.set_content(html);p.add_script_tag(content=source.replace('// SOURCE: 99-instrumentation.js',fixture+extra+'\n// SOURCE: 99-instrumentation.js'));p.locator('#newTown').click();p.locator('#pause').click()
 # Empty queue after a normal funded reset.
 p.evaluate("__townTest.reset('settlement',42)");before=p.evaluate('__edge.snapshot()');q=p.evaluate('__edge.review()');after=p.evaluate('__edge.snapshot()');rows.append({'case':'no waiting essentials','before':before,'review':{'ok':q['ok'],'reason':q['reason']},'after':after});assert not q['ok']and before==after
 # Make a paid, bounded queue using the existing recovery fixture.
 p.evaluate('__queueFixture()');base=p.evaluate('__townTest.save()')
 # Insufficient funding below the existing per-unit purchase minimum.
 p.evaluate('s=>__townTest.load(s)',base);p.evaluate('__edge.poor()');before=p.evaluate('__edge.snapshot()');q=p.evaluate('__edge.review()');after=p.evaluate('__edge.snapshot()');rows.append({'case':'insufficient treasury','before':before,'review':{'ok':q['ok'],'reason':q['reason']},'after':after});assert not q['ok']and before==after
 # Repeated authorization is rejected without a second policy extension.
 p.evaluate('s=>__townTest.load(s)',base);q=p.evaluate('__edge.review()');before=p.evaluate('__edge.snapshot()');r=p.evaluate('__edge.authorize()');middle=p.evaluate('__edge.snapshot()');again=p.evaluate('__edge.authorize()');after=p.evaluate('__edge.snapshot()');rows.append({'case':'repeated confirm','before':before,'first':r,'middle':middle,'second':again,'after':after});assert r['ok']and not again['ok']and middle==after,(r,again,middle,after)
 # A real tick advances queue state and invalidates the old review.
 p.evaluate('s=>__townTest.load(s)',base);q=p.evaluate('__edge.review()');before=p.evaluate('__edge.snapshot()');p.evaluate('__townTest.step(1)');middle=p.evaluate('__edge.snapshot()');r=p.evaluate('__edge.authorize()');after=p.evaluate('__edge.snapshot()');rows.append({'case':'queue changed after quote','before':before,'changed':middle,'result':r,'after':after});assert before!=middle and not r['ok']and middle==after
 # A real square/gathering review is cancelled after the loading quote.
 p.evaluate('s=>__townTest.load(s)',base);event=p.evaluate('__edge.event()');q=p.evaluate('__edge.review()');before=p.evaluate('__edge.snapshot()');assert p.evaluate('id=>__edge.cancel(id)',event);middle=p.evaluate('__edge.snapshot()');r=p.evaluate('__edge.authorize()');after=p.evaluate('__edge.snapshot()');rows.append({'case':'gathering cancelled','before':before,'cancelled':middle,'result':r,'after':after});assert not r['ok']and middle==after and any(x['status']=='cancelled'for x in middle['calendar'])
 assert not errors and p.evaluate('__townTest.validate().ok');b.close()
out=ROOT/'reports/market-loading-edges';out.mkdir(exist_ok=True);(out/'results.json').write_text(json.dumps({'source_sha256':hashlib.sha256(source.encode()).hexdigest(),'rows':rows,'errors':errors},indent=2));print('PASS five loading-choice edge cases; recorded pre/post state and household/municipal cash')
